def header():
 return '''<a class="skip" href="#conteudo">Ir para o conteúdo</a><header class="header"><div class="wrap nav"><a href="/" class="brand" aria-label="GOB-PE LEX — início"><span class="brand-mark" aria-hidden="true">L</span><span><strong>GOB-PE LEX</strong><small>Conhecimento · Fundamento · Clareza</small></span></a><button class="menu-toggle" aria-controls="navegacao" aria-expanded="false">Menu</button><nav class="nav-links" id="navegacao" aria-label="Navegação principal"><a href="/#possibilidades">O assistente</a><a href="/#exemplos">Como consultar</a><a href="/#fundamentos">Fundamentos</a><a class="nav-contact" href="/suporte/">Suporte ↗</a></nav></div></header>'''

